package com.vinhho.onthi10ai.data.solver

import com.vinhho.onthi10ai.data.solver.OfflineQuizBank.RawQuestion

internal object OfflineQuizBankGeography {

    fun buildForGrade(grade: Int): List<RawQuestion> = when (grade) {
        in 1..5 -> primaryQuestions(grade)
        in 6..9 -> secondaryQuestions(grade)
        else -> highSchoolQuestions(grade)
    }

    private fun primaryQuestions(g: Int): List<RawQuestion> {
        val tag = "[Địa lí Lớp $g]"
        return listOf(
            RawQuestion("$tag Việt Nam nằm ở khu vực nào của châu Á?", listOf("Đông Nam Á", "Nam Á", "Tây Á", "Bắc Á"), 0, "Việt Nam thuộc bán đảo Đông Dương, khu vực Đông Nam Á."),
            RawQuestion("$tag Diện tích đất liền Việt Nam có hình dáng giống chữ cái nào?", listOf("Chữ S", "Chữ O", "Chữ L", "Chữ V"), 0, "Lãnh thổ đất liền kéo dài theo chiều Bắc - Nam có dạng hình chữ S."),
            RawQuestion("$tag Thủ đô của nước Cộng hòa Xã hội Chủ nghĩa Việt Nam là:", listOf("Hà Nội", "Thành phố Hồ Chí Minh", "Đà Nẵng", "Hải Phòng"), 0, "Hà Nội là thủ đô và trung tâm chính trị - văn hóa của cả nước."),
            RawQuestion("$tag Vùng biển nước ta nằm ở phía Đông thuộc đại dương nào?", listOf("Thái Bình Dương (Biển Đông)", "Đại Tây Dương", "Ấn Độ Dương", "Bắc Băng Dương"), 0, "Biển Đông là một biển rìa của Thái Bình Dương."),
            RawQuestion("$tag Trên phần đất liền, ba nước có chung đường biên giới với Việt Nam là:", listOf("Trung Quốc, Lào và Campuchia", "Thái Lan, Lào và Mi-an-ma", "Trung Quốc, Thái Lan và Ma-lai-xi-a", "Lào, Cam-pu-chia và Xin-ga-po"), 0, "Phía Bắc giáp Trung Quốc, phía Tây giáp Lào và Campuchia."),
            RawQuestion("$tag Đỉnh núi cao nhất Việt Nam và Đông Dương là:", listOf("Phan-xi-păng (Fansipan)", "Ngọc Linh", "Bạch Mã", "Lang Biang"), 0, "Đỉnh Phan-xi-păng cao 3.147 m thuộc dãy Hoàng Liên Sơn (Lào Cai)."),
            RawQuestion("$tag Đồng bằng rộng lớn và màu mỡ nhất nước ta nằm ở phía Nam là:", listOf("Đồng bằng sông Cửu Long", "Đồng bằng sông Hồng", "Đồng bằng Thanh Hóa", "Đồng bằng Tuy Hòa"), 0, "Đồng bằng sông Cửu Long (Tây Nam Bộ) là vựa lúa lớn nhất Việt Nam."),
            RawQuestion("$tag Đồng bằng lớn thứ hai nước ta nằm ở phía Bắc do sông nào bồi đắp?", listOf("Hệ thống sông Hồng và sông Thái Bình", "Sông Đà Rằng", "Sông Đồng Nai", "Sông Gianh"), 0, "Đồng bằng sông Hồng là cái nôi văn minh lúa nước phía Bắc."),
            RawQuestion("$tag Quần đảo Hoàng Sa thuộc thành phố nào của nước ta?", listOf("Thành phố Đà Nẵng", "Tỉnh Khánh Hòa", "Tỉnh Kiên Giang", "Tỉnh Bà Rịa - Vũng Tàu"), 0, "Huyện đảo Hoàng Sa thuộc thành phố Đà Nẵng."),
            RawQuestion("$tag Quần đảo Trường Sa thuộc tỉnh nào của nước ta?", listOf("Tỉnh Khánh Hòa", "Tỉnh Quảng Ninh", "Thành phố Đà Nẵng", "Tỉnh Cà Mau"), 0, "Huyện đảo Trường Sa thuộc tỉnh Khánh Hòa."),
            RawQuestion("$tag Đảo lớn nhất của Việt Nam nằm ở tỉnh Kiên Giang là đảo nào?", listOf("Đảo Phú Quốc", "Đảo Cát Bà", "Đảo Lý Sơn", "Đảo Côn Sơn"), 0, "Đảo ngọc Phú Quốc có diện tích lớn nhất cả nước."),
            RawQuestion("$tag Khí hậu đặc trưng của miền Bắc Việt Nam có điểm gì khác biệt rõ với miền Nam?", listOf("Có một mùa đông lạnh", "Nóng quanh năm không có mùa đông", "Có tuyết rơi quanh năm", "Không có mùa mưa"), 0, "Miền Bắc chịu ảnh hưởng gió mùa Đông Bắc tạo mùa đông lạnh."),
            RawQuestion("$tag Thành phố nào đông dân nhất Việt Nam hiện nay?", listOf("Thành phố Hồ Chí Minh", "Hà Nội", "Cần Thơ", "Huế"), 0, "TP. Hồ Chí Minh là đô thị lớn nhất và đông dân nhất cả nước."),
            RawQuestion("$tag Việt Nam có bao nhiêu dân tộc anh em cùng sinh sống?", listOf("54 dân tộc", "32 dân tộc", "63 dân tộc", "18 dân tộc"), 0, "Dân tộc Kinh chiếm đa số cùng 53 dân tộc thiểu số đoàn kết."),
            RawQuestion("$tag Vịnh biển nổi tiếng ở Quảng Ninh được UNESCO công nhận là Di sản Thiên nhiên Thế giới là:", listOf("Vịnh Hạ Long", "Vịnh Cam Ranh", "Vịnh Vân Phong", "Vịnh Xuân Đài"), 0, "Vịnh Hạ Long nổi tiếng với hàng nghìn đảo đá vôi kỳ vĩ."),
            RawQuestion("$tag Vùng Tây Nguyên nổi tiếng với loại cây công nghiệp lâu năm nào?", listOf("Cà phê, hồ tiêu, cao su", "Lúa mì và táo", "Củ cải đường", "Cây cọ dầu"), 0, "Đất đỏ bazan ở Tây Nguyên rất thích hợp trồng cà phê, cao su, hồ tiêu."),
            RawQuestion("$tag Ngành giao thông vận tải nào phát triển mạnh nhất ở vùng sông nước Đồng bằng sông Cửu Long?", listOf("Đường thủy (sông ngòi, kênh rạch)", "Đường sắt cao tốc", "Đường ống dẫn dầu", "Đường cáp treo"), 0, "Mạng lưới sông rạch chằng chịt thuận lợi cho ghe thuyền và chợ nổi."),
            RawQuestion("$tag Bốn phương chính trên bản đồ và la bàn là:", listOf("Đông, Tây, Nam, Bắc", "Trên, Dưới, Trái, Phải", "Xuân, Hạ, Thu, Đông", "Trong, Ngoài, Giữa, Bên"), 0, "Đầu phía trên bản đồ thông thường chỉ hướng Bắc."),
            RawQuestion("$tag Trái Đất có dạng hình gì?", listOf("Hình cầu", "Hình vuông", "Mặt phẳng", "Hình lập phương"), 0, "Trái Đất có dạng hình cầu hơi dẹt ở hai cực."),
            RawQuestion("$tag Trên Trái Đất có bao nhiêu châu lục?", listOf("6 châu lục (Á, Âu, Phi, Mỹ, Đại Dương, Nam Cực)", "4 châu lục", "8 châu lục", "3 châu lục"), 0, "Châu Á là châu lục có diện tích lớn nhất."),
            RawQuestion("$tag Đại dương có diện tích lớn nhất trên Trái Đất là:", listOf("Thái Bình Dương", "Đại Tây Dương", "Ấn Độ Dương", "Bắc Băng Dương"), 0, "Thái Bình Dương chiếm gần một nửa diện tích mặt nước thế giới."),
            RawQuestion("$tag Loại đất phù sa màu mỡ nhất thích hợp trồng lúa nước tập trung chủ yếu ở đâu?", listOf("Các đồng bằng châu thổ", "Đỉnh núi cao", "Hoang mạc cát", "Đảo đá vôi"), 0, "Phù sa sông bồi đắp tạo nên đồng bằng phì nhiêu."),
            RawQuestion("$tag Dãy núi dài chạy theo hướng Tây Bắc - Đông Nam ở phía Bắc nước ta là:", listOf("Dãy Hoàng Liên Sơn", "Dãy Bạch Mã", "Dãy Tam Đảo", "Dãy Đông Triều"), 0, "Hoàng Liên Sơn là dãy núi cao và đồ sộ nhất Việt Nam."),
            RawQuestion("$tag Nơi cực Nam trên đất liền nước ta thuộc tỉnh nào?", listOf("Tỉnh Cà Mau (Mũi Cà Mau)", "Tỉnh Hà Giang", "Tỉnh Điện Biên", "Tỉnh Khánh Hòa"), 0, "Đất Mũi Ngọc Hiển, tỉnh Cà Mau là điểm cực Nam trên đất liền."),
            RawQuestion("$tag Điểm cực Bắc của Việt Nam (Lũng Cú) thuộc tỉnh nào?", listOf("Tỉnh Hà Giang", "Tỉnh Lạng Sơn", "Tỉnh Sơn La", "Tỉnh Quảng Ninh"), 0, "Cột cờ Lũng Cú nằm ở huyện Đồng Văn, tỉnh Hà Giang."),
            RawQuestion("$tag Thành phố nào nằm bên bờ sông Hương thơ mộng?", listOf("Thành phố Huế", "Thành phố Vinh", "Thành phố Nha Trang", "Thành phố Biên Hòa"), 0, "Sông Hương và núi Ngự là biểu tượng của cố đô Huế."),
            RawQuestion("$tag Thành phố Đà Lạt nổi tiếng với khí hậu mát mẻ quanh năm nằm trên cao nguyên nào?", listOf("Cao nguyên Lâm Viên", "Cao nguyên Đắk Lắk", "Cao nguyên Mộc Châu", "Cao nguyên Đồng Văn"), 0, "Đà Lạt nằm ở độ cao khoảng 1.500 m trên cao nguyên Lâm Viên."),
            RawQuestion("$tag Con sông dài nhất chảy qua phần lãnh thổ nước ta đổ ra Biển Đông bằng 9 cửa (Cửu Long) là:", listOf("Sông Mê Công (phần ở Việt Nam gọi là sông Tiền và sông Hậu)", "Sông Hồng", "Sông Mã", "Sông Cả"), 0, "Sông Mê Công bồi đắp nên đồng bằng sông Cửu Long trù phú."),
            RawQuestion("$tag Tài nguyên khoáng sản nổi tiếng nhất của tỉnh Quảng Ninh là gì?", listOf("Than đá", "Bô-xít", "A-pa-tít", "Đá quý"), 0, "Quảng Ninh có trữ lượng than đá antraxit lớn nhất cả nước."),
            RawQuestion("$tag Nghề làm muối phát triển mạnh ở vùng nào của nước ta?", listOf("Duyên hải Nam Trung Bộ (Sa Huỳnh, Cà Ná...)", "Vùng núi Tây Bắc", "Cao nguyên đá Đồng Văn", "Vùng trung du Phú Thọ"), 0, "Nam Trung Bộ có nhiều nắng, gió và ít sông lớn đổ ra biển."),
            RawQuestion("$tag Rừng ngập mặn ven biển có tác dụng quan trọng nào?", listOf("Chắn sóng, bảo vệ đê biển và là nơi sinh sống của thủy sản", "Gây lũ lụt", "Làm đất bị nhiễm mặn nặng hơn", "Cản trở ánh nắng mặt trời"), 0, "Rừng ngập mặn Cần Giờ, Cà Mau là lá phổi xanh bảo vệ bờ biển."),
            RawQuestion("$tag Loại hình thiên tai thường xảy ra ở miền Trung nước ta vào mùa thu - đông là:", listOf("Bão và lũ lụt", "Động đất băng hà", "Bão tuyết", "Sóng thần Bắc Cực"), 0, "Bão từ Biển Đông kết hợp địa hình dốc gây mưa lũ lớn ở miền Trung."),
            RawQuestion("$tag Thung lũng Mường Thanh - cánh đồng lớn nhất vùng Tây Bắc thuộc tỉnh nào?", listOf("Điện Biên", "Hòa Bình", "Lào Cai", "Yên Bái"), 0, "'Nhất Thanh, nhì Lò, tam Than, tứ Tấc' - đứng đầu là cánh đồng Mường Thanh (Điện Biên)."),
            RawQuestion("$tag Thành phố cảng lớn nhất miền Bắc nước ta là:", listOf("Hải Phòng", "Thái Nguyên", "Bắc Giang", "Việt Trì"), 0, "Hải Phòng là cửa ngõ hướng biển quan trọng của vùng Đồng bằng sông Hồng."),
