    private fun secondaryQuestions(g: Int): List<RawQuestion> {
        val tag = "[Địa lí Lớp $g]"
        return listOf(
            RawQuestion("$tag Thời gian Trái Đất tự quay hết một vòng quanh trục của nó là:", listOf("24 giờ (1 ngày đêm)", "365 ngày 6 giờ", "12 giờ", "30 ngày"), 0, "Chuyển động tự quay quanh trục sinh ra ngày đêm và sự lệch hướng chuyển động."),
            RawQuestion("$tag Kinh tuyến gốc (0°) đi qua đài thiên văn nào?", listOf("Đài thiên văn Grin-uých (Luân Đôn, Anh)", "Pa-ri (Pháp)", "Niu Oóc (Mỹ)", "Hà Nội (Việt Nam)"), 0, "Kinh tuyến 0° là mốc xác định giờ quốc tế GMT và kinh độ Đông - Tây."),
            RawQuestion("$tag Vòng tròn lớn nhất trên bề mặt Trái Đất chia quả địa cầu thành Bắc bán cầu và Nam bán cầu là:", listOf("Đường Xích đạo (vĩ tuyến 0°)", "Chí tuyến Bắc", "Vòng cực Nam", "Kinh tuyến 180°"), 0, "Xích đạo là vĩ tuyến gốc dài nhất."),
            RawQuestion("$tag Lớp vỏ Trái Đất có cấu tạo gồm những mảng lớn nào chuyển dịch chậm trên lớp Manti?", listOf("Các mảng kiến tạo", "Các tầng khí quyển", "Các dòng hải lưu", "Các vành đai mây"), 0, "Sự xô vào nhau hay tách giãn của các mảng kiến tạo gây ra núi lửa và động đất."),
            RawQuestion("$tag Dụng cụ dùng để đo nhiệt độ không khí là gì?", listOf("Nhiệt kế", "Ẩm kế", "Khí áp kế", "Vũ kế"), 0, "Ẩm kế đo độ ẩm, khí áp kế đo khí áp, vũ kế đo lượng mưa."),
            RawQuestion("$tag Khí hậu Việt Nam mang tính chất cơ bản nào?", listOf("Nhiệt đới ẩm gió mùa", "Ôn đới hải dương", "Hàn đới cực", "Hoang mạc lục địa"), 0, "Lượng bức xạ lớn, độ ẩm cao trên 80% và có hai mùa gió chính."),
            RawQuestion("$tag Gió mùa Đông Bắc thổi vào miền Bắc nước ta vào mùa đông có tính chất ban đầu là:", listOf("Lạnh và khô", "Nóng và ẩm", "Lạnh và rất ẩm ngay từ đầu", "Khô nóng như gió Lào"), 0, "Nửa đầu mùa đông từ áp cao Xi-bia xuống gây hanh khô; cuối mùa qua biển gây mưa phùn."),
            RawQuestion("$tag Gió Phơn Tây Nam khô nóng ở Bắc Trung Bộ thường được gọi là gì?", listOf("Gió Lào", "Gió Tín phong", "Gió Bấc", "Gió Nồm"), 0, "Vượt qua dãy Trường Sơn, gió mất hơi ẩm nên tràn xuống đồng bằng rất khô nóng."),
            RawQuestion("$tag Hệ thống sông ngòi Việt Nam có đặc điểm mật độ như thế nào?", listOf("Mạng lưới sông ngòi dày đặc, nhiều sông nhỏ ngắn và dốc", "Rất thưa thớt sông", "Chỉ có duy nhất 1 con sông", "Sông đóng băng vào mùa đông"), 0, "Nước ta có 2.360 con sông dài từ 10 km trở lên."),
            RawQuestion("$tag Diện tích phần đất liền và các hải đảo của Việt Nam xấp xỉ bao nhiêu?", listOf("331.212 km²", "150.000 km²", "960.000 km²", "1.200.000 km²"), 0, "Theo Niên giám thống kê, tổng diện tích đất tự nhiên khoảng 331,2 nghìn km²."),
