            RawQuestion("$tag Độ muối trung bình của nước biển và đại dương trên thế giới vào khoảng bao nhiêu?", listOf("35‰ (35 phần nghìn)", "10‰", "70‰", "100‰"), 0, "Thay đổi theo vĩ độ, lượng mưa, độ bốc hơi và lượng nước sông đổ vào."),
